def sample_annual_operation_plan(rows: list[dict] | None = None) -> dict:
    rows = [sample_aihr_matrix_row()] if rows is None else rows
    operation_rows = []
    for index, row in enumerate(rows, start=1):
        fit = row.get("course_fit") or {}
        delivery = row.get("delivery_operation") or {}
        constraint = delivery.get("constraint_fit") if isinstance(delivery.get("constraint_fit"), dict) else {}
        method = delivery.get("method_constraint_fit") if isinstance(delivery.get("method_constraint_fit"), dict) else {}
        time = delivery.get("time_constraint_fit") if isinstance(delivery.get("time_constraint_fit"), dict) else {}
        facility = row.get("facility_constraint_fit") or delivery.get("facility_constraint_fit") or {}
        decision = row.get("decision_state") or {}
        review = row.get("human_review") or {}
        chain = row.get("evidence_chain") or {}
        completeness = chain.get("completeness") or {}
        operation_rows.append(
            {
                "sequence": index,
                "recommended_window": "Q1",
                "phase": "core_gap_training",
                "course_name": row.get("course_name"),
                "training_course_id": row.get("training_course_id"),
                "target_population": "HR staff",
                "need_classification": (row.get("need_classification") or {"code": "required"}).get("code", "required"),
                "system_suggestion": decision.get("system_suggestion", "required"),
                "decision_status": decision.get("status", "pending_human_decision"),
                "human_review_severity": review.get("severity", "ready"),
                "evidence_chain_status": completeness.get("status", "complete"),
                "hours": fit.get("hours"),
                "methods": fit.get("methods", []),
                "facilities": fit.get("facilities", []),
                "constraint_status": constraint.get("status", "fit"),
                "method_status": method.get("status", "not_requested"),
                "time_status": time.get("status", "not_requested"),
                "facility_status": facility.get("status", "fit"),
                "review_flags": row.get("review_flags", []),
                "scheduling_rationale": "Run after scope confirmation.",
            }
        )
    return {
        "schema": "aihr_annual_operation_plan_seed_v1",
        "guide_stage": "C2-2",
        "status": "needs_human_review",
        "purpose": "Draft annual operation-plan seed generated from the training-system matrix; it is not an approved annual plan.",
        "target_population": "HR staff",
        "requested_constraints": {"preferred_max_hours": 24, "preferred_methods": ["offline"], "preferred_facilities": []},
        "summary": {
            "row_count": len(operation_rows),
            "estimated_total_hours": sum(float(item["hours"] or 0) for item in operation_rows),
            "hours_known_count": len(operation_rows),
            "pending_human_decision_rows": len(operation_rows),
            "review_required_rows": 0,
        },
        "rows": operation_rows,
        "review_gate": {
            "status": "blocked_until_human_decision",
            "approval_claim": False,
            "message": "Use this as an operation-planning seed only.",
        },
        "export_fields": [
            "recommended_window",
            "phase",
            "target_population",
            "course_name",
            "need_classification",
            "hours",
            "methods",
            "facilities",
            "constraint_status",
            "decision_status",
            "human_review_severity",
        ],
    }


