def sample_training_necessity_review(rows: list[dict] | None = None) -> dict:
    rows = [sample_aihr_matrix_row()] if rows is None else rows
    review_rows = []
    for index, row in enumerate(rows, start=1):
        fit = row.get("course_fit") or {}
        scope = row.get("course_scope_fit") or {}
        direct = row.get("evidence_directness") or row.get("course_link", {}).get("evidence_directness") or {}
        basis = row.get("task_ksa_basis") or {}
        decision = row.get("decision_state") or {}
        review = row.get("human_review") or {}
        review_rows.append(
            {
                "sequence": index,
                "course_name": row.get("course_name"),
                "training_course_id": row.get("training_course_id"),
                "job_linkage": {
                    "status": "evidence_visible",
                    "course_scope_relation": scope.get("relation", "direct_scope_unit"),
                    "course_scope_alignment": scope.get("alignment", "direct"),
                    "evidence_directness": direct.get("code", "training_goal_token"),
                    "task_ksa_basis_counts": {
                        "target_scope_ksa": len(basis.get("target_scope_ksa", [])),
                        "gap_ksa": len(basis.get("gap_ksa", [])),
                        "training_goal_ksa": len(basis.get("training_goal_ksa", [])),
                        "covered_elements": len(basis.get("covered_elements", [])),
                    },
                    "review_reason": "Task/KSA and scope evidence are visible.",
                },
                "level_fit": {
                    "status": "evidence_visible",
                    "target_level_band": row.get("target_level_band", {}),
                    "course_level": fit.get("level"),
                    "review_reason": "Course level and target level band are visible.",
                },
                "required_optional_review": {
                    "code": (row.get("required_optional_basis") or {}).get("code", "required"),
                    "label": (row.get("required_optional_basis") or {}).get("label", "required"),
                    "rationale": (row.get("required_optional_basis") or {}).get("rationale", ""),
                    "statutory_or_mandatory_basis": "not_supplied",
                    "approval_claim": False,
                },
                "duplicate_or_generic_review": {
                    "status": "clear",
                    "codes": [],
                    "duplicate_or_generic_warning": row.get("duplicate_or_generic_warning", {}),
                    "specificity_warning": row.get("specificity_warning", {}),
                    "mapping_strength_warning": row.get("mapping_strength_warning", {}),
                },
                "delivery_feasibility": {
                    "status": "fit",
                    "constraint_status": "fit",
                    "hours": fit.get("hours"),
                    "methods": fit.get("methods", []),
                    "facilities": fit.get("facilities", []),
                    "requested_constraints": {"preferred_max_hours": 24},
                    "constraint_fit": {"status": "fit", "dimensions": {"method": "fit", "time": "fit", "facility": "fit"}},
                },
                "performance_contribution": {
                    "status": "evidence_visible",
                    "evidence_chain_status": "complete",
                    "gap_ksa": basis.get("gap_ksa", []),
                    "training_goal_ksa": basis.get("training_goal_ksa", []),
                    "covered_elements": basis.get("covered_elements", []),
                    "review_reason": "KSA or covered element evidence is visible.",
                },
                "decision_state": decision,
                "human_review": review,
                "review_flags": row.get("review_flags", []),
                "recommended_review_action": "human_confirm_before_use",
            }
        )
    return {
        "schema": "aihr_training_necessity_review_v1",
        "guide_stage": "C1-2",
        "status": "review_evidence_prepared",
        "purpose": "C1-2 necessity-review contract.",
        "target_population": "HR staff",
        "requested_constraints": {"preferred_max_hours": 24},
        "review_dimensions": [
            "job_linkage",
            "level_fit",
            "required_optional_review",
            "duplicate_or_generic_review",
            "delivery_feasibility",
            "performance_contribution",
            "human_review",
        ],
        "summary": {
            "row_count": len(review_rows),
            "review_required_rows": len(review_rows),
            "approval_blocked_rows": len(review_rows),
            "job_linkage_status_counts": {"evidence_visible": len(review_rows)},
            "level_fit_status_counts": {"evidence_visible": len(review_rows)},
            "delivery_feasibility_status_counts": {"fit": len(review_rows)},
            "duplicate_or_generic_status_counts": {"clear": len(review_rows)},
            "performance_contribution_status_counts": {"evidence_visible": len(review_rows)},
            "required_optional_counts": {"required": len(review_rows)},
            "decision_state_counts": {"pending_human_decision": len(review_rows)},
        },
        "rows": review_rows,
        "validation_rules": [
            "Do not confirm a course from course_name alone.",
        ],
        "review_gate": {
            "status": "pending_human_confirmation",
            "approval_claim": False,
            "message": "No course list is approved by automation.",
        },
    }


AIHR_TEST_ISOLATION_ENV_VARS = tuple(
    dict.fromkeys(
        [
            "NCS_AIHR_AGENT_QUEUE_JSON_PATH",
            *AIHR_DASHBOARD_STATIC_ARTIFACT_ENV.values(),
        ]
    )
)


class HarnessTests(unittest.TestCase):
    def setUp(self) -> None:
        self._saved_aihr_env = {
            key: os.environ.pop(key, None) for key in AIHR_TEST_ISOLATION_ENV_VARS
        }

    def tearDown(self) -> None:
        for key in AIHR_TEST_ISOLATION_ENV_VARS:
            os.environ.pop(key, None)
        for key, value in self._saved_aihr_env.items():
            if value is not None:
                os.environ[key] = value

    def run_harness_cli_json(self, argv: list[str]) -> dict:
        previous_argv = sys.argv[:]
        stdout = io.StringIO()
        sys.argv = ["ncs_harness.py", *argv]
        try:
            with contextlib.redirect_stdout(stdout):
                main()
        finally:
            sys.argv = previous_argv
        return json.loads(stdout.getvalue())

    def seed_readonly_smoke_db(self, db_path: Path) -> int:
        conn = sqlite3.connect(db_path)
        try:
            conn.execute("CREATE TABLE readonly_sentinel(id INTEGER PRIMARY KEY, value TEXT)")
            conn.execute("INSERT INTO readonly_sentinel(value) VALUES ('unchanged')")
            conn.commit()
        finally:
            conn.close()
        return db_path.stat().st_mtime_ns

    def assert_readonly_smoke_db_unchanged(self, db_path: Path, before_mtime_ns: int) -> None:
        self.assertEqual(db_path.stat().st_mtime_ns, before_mtime_ns)
        conn = sqlite3.connect(db_path)
        try:
            count = conn.execute("SELECT COUNT(*) FROM readonly_sentinel").fetchone()[0]
            values = [
                row[0]
                for row in conn.execute("SELECT value FROM readonly_sentinel ORDER BY id")
            ]
        finally:
            conn.close()
        self.assertEqual(count, 1)
        self.assertEqual(values, ["unchanged"])

    def test_retry_qualification_errors_cli_blocks_when_ncs006_guard_blocks(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            checkpoint_path = Path(tmp) / "checkpoint_ncs006_element_api_status_20260625.json"
            checkpoint_path.write_text(
                json.dumps(
                    {
                        "generated_at": "2026-06-25T00:00:00+00:00",
                        "next_safe_action": {
                            "status": "wait_for_rate_limit_cooldown",
                            "api_call_allowed_now": False,
                        },
                        "rate_limit_cooldown": {
                            "status": "cooldown_active",
                            "cooldown_until": "2999-01-01T00:00:00+00:00",
                        },
                    },
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
            previous_argv = sys.argv[:]
            stdout = io.StringIO()
            sys.argv = [
                "ncs_harness.py",
                "retry-qualification-errors",
                "--ncs006-checkpoint-path",
                str(checkpoint_path),
            ]
            try:
                with contextlib.redirect_stdout(stdout):
                    with patch("ncs_harness.retry_qualification_error_units") as retry_mock:
                        with self.assertRaises(SystemExit) as raised:
                            main()
            finally:
                sys.argv = previous_argv

        payload = json.loads(stdout.getvalue())
        self.assertEqual(raised.exception.code, 2)
        self.assertFalse(payload["ok"])
        self.assertEqual(payload["error"], "qualification_retry_guard_blocked")
        self.assertFalse(payload["qualification_retry_allowed_now"])
        self.assertIn("ncs006_rate_limit_cooldown_active", payload["safety_violations"])
        retry_mock.assert_not_called()

    def test_retry_qualification_errors_cli_runs_when_ncs006_guard_allows(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            checkpoint_path = tmp_path / "checkpoint_ncs006_element_api_status_20260625.json"
            checkpoint_path.write_text(
                json.dumps(
                    {
                        "generated_at": "2026-06-25T00:00:00+00:00",
                        "next_safe_action": {
                            "status": "start_guarded_watchdog_if_no_active_process",
                            "api_call_allowed_now": False,
                            "qualification_retry_allowed_now": True,
                        },
                    },
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
            previous_argv = sys.argv[:]
            stdout = io.StringIO()
            sys.argv = [
                "ncs_harness.py",
                "retry-qualification-errors",
                "--ncs006-checkpoint-path",
                str(checkpoint_path),
                "--report-path",
                str(tmp_path / "qualification_error_report.md"),
            ]
            settings = SimpleNamespace(
                db_path=tmp_path / "ncs.db",
                qualification_service_key="service-key",
            )
            try:
                with contextlib.redirect_stdout(stdout):
                    with patch("ncs_harness.load_settings", return_value=settings):
                        with patch(
                            "ncs_harness.retry_qualification_error_units",
                            return_value={"ok": True, "error_report": {}},
                        ) as retry_mock:
                            main()
            finally:
                sys.argv = previous_argv

        payload = json.loads(stdout.getvalue())
        self.assertTrue(payload["ok"])
        self.assertTrue(payload["qualification_retry_allowed_now"])
        self.assertEqual(payload["api_execution_guard"]["status"], "allowed")
        retry_mock.assert_called_once()

