    def test_quality_gates_cli_passes_non_hr_surface_artifacts(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            out_path = tmp_path / "quality.json"
            markdown_path = tmp_path / "quality.md"
            query_path = tmp_path / "query.json"
            transition_path = tmp_path / "transition.json"
            plan_path = tmp_path / "plan.json"
            previous_argv = sys.argv[:]
            stdout = io.StringIO()
            sys.argv = [
                "ncs_harness.py",
                "quality-gates",
                "--include-transition-eval",
                "--transition-limit",
                "3",
                "--transition-scenario-limit",
                "4",
                "--non-hr-query-smoke-report",
                str(query_path),
                "--non-hr-transition-smoke-report",
                str(transition_path),
                "--non-hr-education-plan-smoke-report",
                str(plan_path),
                "--out",
                str(out_path),
                "--markdown-out",
                str(markdown_path),
            ]
            result_payload = {
                "ok": True,
                "status": "pass",
                "gates": [],
                "evidence": {},
            }
            try:
                with (
                    patch("ncs_harness.load_settings", return_value=SimpleNamespace(db_path=tmp_path / "ncs.db")),
                    patch("ncs_harness.evaluate_quality_gates", return_value=result_payload) as evaluate,
                    contextlib.redirect_stdout(stdout),
                ):
                    main()
            finally:
                sys.argv = previous_argv

        payload = json.loads(stdout.getvalue())
        self.assertTrue(payload["ok"])
        call_kwargs = evaluate.call_args.kwargs
        self.assertTrue(call_kwargs["include_transition_evaluation"])
        self.assertEqual(call_kwargs["transition_limit"], 3)
        self.assertEqual(call_kwargs["transition_scenario_limit"], 4)
        self.assertEqual(call_kwargs["out_path"], out_path)
        self.assertEqual(call_kwargs["markdown_path"], markdown_path)
        self.assertEqual(
            call_kwargs["non_hr_surface_artifact_paths"],
            {
                "non_hr_query_smoke": query_path,
                "non_hr_transition_smoke": transition_path,
                "non_hr_education_plan_smoke": plan_path,
            },
        )

