    def test_connect_readonly_sqlite_blocks_writes_to_existing_database(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            db_path = Path(tmp) / "ncs.db"
            before_mtime_ns = self.seed_readonly_smoke_db(db_path)

            conn = _connect_readonly_sqlite(db_path)
            try:
                self.assertEqual(
                    conn.execute("SELECT COUNT(*) FROM readonly_sentinel").fetchone()["COUNT(*)"],
                    1,
                )
                with self.assertRaises(sqlite3.OperationalError):
                    conn.execute("INSERT INTO readonly_sentinel(value) VALUES ('mutated')")
            finally:
                conn.close()

            self.assert_readonly_smoke_db_unchanged(db_path, before_mtime_ns)

    def test_export_ontology_definition_seedpack_cli_filters_definition_blockers(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            db_path = tmp_path / "ncs.db"
            out_path = tmp_path / "definition_seedpack.jsonl"
            markdown_path = tmp_path / "definition_seedpack.md"
            csv_path = tmp_path / "definition_seedpack.csv"
            conn = connect(db_path)
            try:
                initialize_database(conn)
                timestamp = now_utc()
                for name, issue_type in (
                    ("workforce planning knowledge", "hr_core_concept_human_review_required"),
                    ("competency gap analysis", "ontology_core_concept_human_review_required"),
                ):
                    cur = conn.execute(
                        """
                        INSERT INTO ontology_concepts(
                            concept_name, normalized_key, concept_type, definition_status,
                            relation_status, review_status, created_at, updated_at
                        ) VALUES (?, ?, 'knowledge', 'missing', 'none', 'candidate', ?, ?)
                        """,
                        (
                            name,
                            name.replace(" ", ""),
                            timestamp,
                            timestamp,
                        ),
                    )
                    concept_id = cur.lastrowid
                    conn.execute(
                        """
                        INSERT INTO quality_issues(
                            target_type, target_id, issue_type, severity,
                            issue_detail, suggested_action, detected_at
                        ) VALUES ('ontology_concept', ?, ?, 'warning',
                                  'Definition needs human review', 'Review definition', ?)
                        """,
                        (str(concept_id), issue_type, timestamp),
                    )
                conn.execute(
                    """
                    INSERT INTO quality_issues(
                        target_type, target_id, issue_type, severity,
                        issue_detail, suggested_action, detected_at
                    ) VALUES ('unit', 'U-1', 'criteria_format_issue', 'warning',
                              'Noise issue', 'Ignore for this seedpack', ?)
                    """,
                    (timestamp,),
                )
                conn.commit()
                unresolved_before = conn.execute(
                    "SELECT COUNT(*) AS count FROM quality_issues WHERE resolved_at IS NULL"
                ).fetchone()["count"]
            finally:
                conn.close()
            before_mtime_ns = db_path.stat().st_mtime_ns

            with patch("ncs_harness.load_settings", return_value=SimpleNamespace(db_path=db_path)):
                result = self.run_harness_cli_json(
                    [
                        "export-ontology-definition-seedpack",
                        "--limit",
                        "10",
                        "--per-issue-type-limit",
                        "5",
                        "--out",
                        str(out_path),
                        "--markdown-out",
                        str(markdown_path),
                        "--csv-out",
                        str(csv_path),
                        "--source-report-path",
                        "reports/aihr_review_priority_20260623.md",
                    ]
                )
            after_export_mtime_ns = db_path.stat().st_mtime_ns

            conn = connect(db_path)
            try:
                unresolved_after = conn.execute(
                    "SELECT COUNT(*) AS count FROM quality_issues WHERE resolved_at IS NULL"
                ).fetchone()["count"]
            finally:
                conn.close()
            records = [
                json.loads(line)
                for line in out_path.read_text(encoding="utf-8").splitlines()
            ]
            with csv_path.open("r", encoding="utf-8-sig", newline="") as handle:
                csv_rows = list(csv.DictReader(handle))
            markdown_text = markdown_path.read_text(encoding="utf-8")

        self.assertTrue(result["ok"])
        self.assertEqual(result["item_count"], 2)
