        self.assertFalse(result["status_update_allowed"])
        self.assertFalse(result["db_writes"])
        self.assertFalse(result["approval_claim"])
        self.assertEqual(unresolved_before, unresolved_after)
        self.assertEqual(after_export_mtime_ns, before_mtime_ns)
        batch = records[0]
        items = records[1:]
        self.assertEqual(batch["issue_types"], ONTOLOGY_DEFINITION_REVIEW_ISSUE_TYPES)
        self.assertEqual(
            sorted(item["issue_type"] for item in items),
            sorted(ONTOLOGY_DEFINITION_REVIEW_ISSUE_TYPES),
        )
        self.assertEqual({item["target_type"] for item in items}, {"ontology_concept"})
        self.assertEqual([row["decision"] for row in csv_rows], ["", ""])
        self.assertEqual([row["human_decision_required"] for row in csv_rows], ["True", "True"])
        self.assertEqual([row["status_update_allowed"] for row in csv_rows], ["False", "False"])
        self.assertEqual([row["db_writes"] for row in csv_rows], ["False", "False"])
        self.assertEqual([row["approval_claim"] for row in csv_rows], ["False", "False"])
        self.assertIn("export-ontology-definition-seedpack", markdown_text)

