    def test_ksa_label_policy_v2_sampling_plan_cli_rejects_unsafe_source(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            source_path = tmp_path / "unsafe_ksa_label_auto_triage.json"
            json_path = tmp_path / "sampling_plan.json"
            markdown_path = tmp_path / "sampling_plan.md"
            csv_path = tmp_path / "sampling_plan.csv"
            source_path.write_text(
                json.dumps(
                    {
                        "schema": "ksa_label_auto_triage_report_v1",
                        "ok": True,
                        "report_only": True,
                        "status_update_allowed": False,
                        "db_writes": True,
                        "approval_claim": False,
                        "safety": {
                            "status_update_allowed": False,
                            "db_writes": False,
                            "approval_claim": False,
                            "human_reviewed_written_by_report": False,
                            "accepted_written_by_report": False,
                            "reviewed_written_by_report": False,
                        },
                        "classification_v2_counts": {},
                        "major_bucket_rollup": [],
                    },
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
            previous_argv = sys.argv[:]
            stdout = io.StringIO()
            sys.argv = [
                "ncs_harness.py",
                "ksa-label-policy-v2-sampling-plan",
                "--source-report",
                str(source_path),
                "--out",
                str(json_path),
                "--markdown-out",
                str(markdown_path),
                "--csv-out",
                str(csv_path),
            ]
            try:
                with contextlib.redirect_stdout(stdout):
                    with self.assertRaises(SystemExit) as raised:
                        main()
            finally:
                sys.argv = previous_argv

            payload = json.loads(stdout.getvalue())
            report = json.loads(json_path.read_text(encoding="utf-8"))
            self.assertEqual(raised.exception.code, 1)
            self.assertFalse(payload["ok"])
            self.assertFalse(report["ok"])
            self.assertEqual(report["status"], "invalid_source_report")
            self.assertIn("db_writes_not_false", report["source_issues"])
            self.assertFalse(report["status_update_allowed"])
            self.assertFalse(report["db_writes"])
            self.assertFalse(report["approval_claim"])
            with csv_path.open("r", encoding="utf-8-sig", newline="") as handle:
                rows = list(csv.DictReader(handle))
            self.assertEqual(rows, [])

