    def test_ksa_missing_label_gap_review_pack_cli_writes_readonly_operator_pack(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            db_path = tmp_path / "ncs.db"
            self.seed_ksa_label_fixture(db_path)
            conn = connect(db_path)
            try:
                timestamp = now_utc()
                orphan_concept_id = conn.execute(
                    """
                    INSERT INTO ontology_concepts(
                        concept_name, normalized_key, concept_type, definition_status,
                        relation_status, review_status, created_at, updated_at
                    ) VALUES ('=orphan missing label concept', 'orphanmissinglabelconcept',
                              'knowledge', 'missing', 'none', 'candidate', ?, ?)
                    """,
                    (timestamp, timestamp),
                ).lastrowid
                linked_ksa_id = conn.execute(
                    """
                    INSERT INTO ksa_items(element_id, ksa_type_code, ksa_type_name, ksa_no, ksa_text_raw)
                    VALUES (
                        (SELECT element_id FROM competency_elements WHERE unit_code = '0202020101_23v3'),
                        '01', 'knowledge', '9', '=linked missing label source evidence'
                    )
                    """
                ).lastrowid
                linked_concept_id = conn.execute(
                    """
                    INSERT INTO ontology_concepts(
                        concept_name, normalized_key, concept_type, definition_status,
                        relation_status, review_status, created_at, updated_at
                    ) VALUES ('=linked missing label concept', 'linkedmissinglabelconcept',
                              'knowledge', 'missing', 'none', 'candidate', ?, ?)
                    """,
                    (timestamp, timestamp),
                ).lastrowid
                conn.execute(
                    """
                    INSERT INTO ksa_concept_links(ksa_id, concept_id, link_status, created_at)
                    VALUES (?, ?, 'candidate', ?)
                    """,
                    (linked_ksa_id, linked_concept_id, timestamp),
                )
                atomic_id = conn.execute(
                    """
                    INSERT INTO ksa_atomic_items(
                        ksa_id, element_id, ksa_type_name, atom_index, atom_text,
                        normalized_key, split_method, review_status, created_at
                    ) VALUES (
                        ?,
                        (SELECT element_id FROM competency_elements WHERE unit_code = '0202020101_23v3'),
                        'knowledge', 99, '=atomic missing label source evidence',
                        'atomicmissinglabelsourceevidence', 'test', 'candidate', ?
                    )
                    """,
                    (linked_ksa_id, timestamp),
                ).lastrowid
                atomic_concept_id = conn.execute(
                    """
                    INSERT INTO ontology_concepts(
                        concept_name, normalized_key, concept_type, definition_status,
                        relation_status, review_status, created_at, updated_at
                    ) VALUES ('=atomic missing label concept', 'atomicmissinglabelconcept',
                              'knowledge', 'missing', 'none', 'candidate', ?, ?)
                    """,
                    (timestamp, timestamp),
                ).lastrowid
                conn.execute(
                    """
                    INSERT INTO ksa_atomic_concept_links(atomic_id, concept_id, link_status, created_at)
                    VALUES (?, ?, 'candidate', ?)
                    """,
                    (atomic_id, atomic_concept_id, timestamp),
                )
                criteria_id = conn.execute(
                    """
                    INSERT INTO performance_criteria(element_id, criteria_no, criteria_text_raw)
                    VALUES (
                        (SELECT element_id FROM competency_elements WHERE unit_code = '0202020101_23v3'),
                        '99', '=criteria missing label source evidence'
                    )
                    """
                ).lastrowid
                criteria_concept_id = conn.execute(
                    """
                    INSERT INTO ontology_concepts(
                        concept_name, normalized_key, concept_type, definition_status,
                        relation_status, review_status, created_at, updated_at
                    ) VALUES ('=criteria missing label concept', 'criteriamissinglabelconcept',
                              'knowledge', 'missing', 'none', 'candidate', ?, ?)
                    """,
                    (timestamp, timestamp),
                ).lastrowid
                conn.execute(
                    """
                    INSERT INTO criteria_concept_links(criteria_id, concept_id, relation_type, link_status, created_at)
                    VALUES (?, ?, 'related', 'candidate', ?)
                    """,
                    (criteria_id, criteria_concept_id, timestamp),
                )
                self.assertIsNotNone(orphan_concept_id)
                conn.commit()
            finally:
                conn.close()
            before_mtime_ns = db_path.stat().st_mtime_ns
            json_path = tmp_path / "missing_label_gap.json"
            markdown_path = tmp_path / "missing_label_gap.md"
            csv_path = tmp_path / "missing_label_gap.csv"

            with patch("ncs_harness.load_settings", return_value=SimpleNamespace(db_path=db_path)):
                result = self.run_harness_cli_json(
                    [
                        "ksa-missing-label-gap-review-pack",
                        "--out",
                        str(json_path),
                        "--markdown-out",
                        str(markdown_path),
                        "--csv-out",
                        str(csv_path),
                        "--limit",
                        "10",
                    ]
                )

            report = json.loads(json_path.read_text(encoding="utf-8"))
            markdown = markdown_path.read_text(encoding="utf-8")
            self.assertTrue(result["ok"])
            self.assertEqual(report["schema"], "ksa_missing_label_gap_review_pack_v1")
            self.assertEqual(db_path.stat().st_mtime_ns, before_mtime_ns)
            self.assertEqual(report["missing_label_gap_count"], 3)
            self.assertEqual(report["reviewable_missing_label_gap_count"], 3)
            self.assertEqual(report["orphan_raw_concept_backlog_count"], 1)
            self.assertEqual(report["emitted_row_count"], 3)
            self.assertFalse(report["output_limit_applied"])
            self.assertFalse(report["status_update_allowed"])
            self.assertFalse(report["db_writes"])
            self.assertFalse(report["approval_claim"])
            self.assertTrue(report["safety"]["missing_label_gap_is_not_button_review_row"])
            self.assertTrue(report["safety"]["orphan_raw_concepts_excluded_from_review_rows"])
            emitted_names = {row["concept_name"] for row in report["rows"]}
            self.assertEqual(
                emitted_names,
                {
                    "=linked missing label concept",
                    "=atomic missing label concept",
                    "=criteria missing label concept",
                },
            )
            self.assertNotIn("=orphan missing label concept", emitted_names)
            for row in report["rows"]:
                self.assertGreater(
                    row["ksa_link_count"] + row["atomic_link_count"] + row["criteria_link_count"],
                    0,
                )
                self.assertFalse(row["is_button_review_row"])
                self.assertEqual(
                    row["operator_action"],
                    "create_or_review_short_label_candidate_from_source_evidence",
                )
            self.assertIn("not button-style approval rows", markdown)
            self.assertIn("orphan_raw_concept_backlog", markdown)
            with csv_path.open("r", encoding="utf-8-sig", newline="") as handle:
                rows = list(csv.DictReader(handle))
            self.assertEqual(len(rows), 3)
            self.assertEqual(rows[0]["schema"], "ksa_missing_label_gap_decision_sheet_v1")
            self.assertEqual(
                {row["concept_name"] for row in rows},
                {
                    "'=linked missing label concept",
                    "'=atomic missing label concept",
                    "'=criteria missing label concept",
                },
            )
            self.assertEqual(rows[0]["decision"], "")
            self.assertEqual(rows[0]["reviewer_id"], "")
            self.assertEqual(rows[0]["status_update_allowed"], "False")
            self.assertEqual(rows[0]["db_writes"], "False")
            self.assertEqual(rows[0]["approval_claim"], "False")
            self.assertEqual(result["csv"]["record_count"], 3)

