        self.assertTrue(report["ksa_items"]["raw_text_multiset_sha256"].startswith("sha256:"))
        self.assertEqual(
            report["ontology_definitions"]["missing_columns"],
            ["definition_source", "definition_status", "review_status"],
        )
        self.assertIn("missing_column:ontology_concepts.definition_status", markdown)

