    def test_ksa_immutability_raw_text_baseline_allows_rebuilt_row_ids(self) -> None:
        def _minimal_conn(ksa_id: int, element_id: int) -> sqlite3.Connection:
            conn = sqlite3.connect(":memory:")
            conn.row_factory = sqlite3.Row
            conn.execute(
                """
                CREATE TABLE ksa_items(
                    ksa_id INTEGER PRIMARY KEY,
                    element_id INTEGER,
                    ksa_type_code TEXT,
                    ksa_type_name TEXT,
                    ksa_no TEXT,
                    ksa_text_raw TEXT
                )
                """
            )
            conn.execute(
                """
                CREATE TABLE ontology_concepts(
                    concept_id INTEGER PRIMARY KEY,
                    concept_name TEXT,
                    concept_type TEXT,
                    definition TEXT,
                    definition_source TEXT,
                    definition_status TEXT,
                    review_status TEXT
                )
                """
            )
            conn.execute(
                """
                INSERT INTO ksa_items(
                    ksa_id, element_id, ksa_type_code, ksa_type_name, ksa_no, ksa_text_raw
                ) VALUES (?, ?, '01', 'knowledge', '1', 'same source text')
                """,
                (ksa_id, element_id),
            )
            conn.execute(
                """
                INSERT INTO ontology_concepts(
                    concept_id, concept_name, concept_type, definition,
                    definition_source, definition_status, review_status
                ) VALUES (1, 'Same concept', 'knowledge', '', '', 'missing', 'model_preprocessed')
                """
            )
            conn.commit()
            return conn

        first_conn = _minimal_conn(1, 10)
        try:
            first_report = build_ksa_immutability_audit(first_conn)
        finally:
            first_conn.close()
        second_conn = _minimal_conn(99, 20)
        try:
            second_report = build_ksa_immutability_audit(
                second_conn,
                baseline_sha256=first_report["ksa_items"]["sha256"],
                baseline_raw_text_multiset_sha256=first_report["ksa_items"][
                    "raw_text_multiset_sha256"
                ],
            )
        finally:
            second_conn.close()

        self.assertTrue(second_report["ok"], second_report["issues"])
        self.assertFalse(second_report["baseline"]["matches_current"])
        self.assertTrue(second_report["baseline"]["raw_text_multiset_matches_current"])
        self.assertTrue(second_report["baseline"]["source_text_matches_current"])
        self.assertIn(
            "baseline_row_identity_hash_mismatch_raw_text_matches",
            second_report["warnings"],
        )

