    def test_api_unmatched_diagnosis_cli_writes_readonly_artifacts(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            db_path = tmp_path / "ncs.db"
            conn = connect(db_path)
            initialize_database(conn)
            timestamp = now_utc()
            for issue_type, target_id, detail, resolved in (
                ("api_element_unmatched", "101", "NCS006 request failed after retries.", False),
                ("api_element_unmatched", "102", "NCS006 request failed after retries.", True),
                ("api_element_collection_failure", "103", "API collection failed after retries.", False),
                ("api_element_collection_failure", "104", "API collection failed after retries.", True),
                ("api_value_mismatch", "105", "unit_name mismatch.", False),
                ("api_element_value_mismatch", "106", "element_level mismatch.", False),
            ):
                insert_quality_issue(
                    conn,
                    target_type="element",
                    target_id=target_id,
                    issue_type=issue_type,
                    severity="warning",
                    issue_detail=detail,
                    suggested_action="Review.",
                )
                if resolved:
                    issue_id = int(conn.execute("SELECT last_insert_rowid()").fetchone()[0])
                    conn.execute(
                        "UPDATE quality_issues SET resolved_at = ? WHERE issue_id = ?",
                        (timestamp, issue_id),
                    )
            conn.commit()
            conn.close()

            diagnosis_path = tmp_path / "api_unmatched_diagnosis.json"
            diagnosis_md = tmp_path / "api_unmatched_diagnosis.md"
            proposal_path = tmp_path / "api_unmatched_cleanup_proposal.json"
            proposal_md = tmp_path / "api_unmatched_cleanup_proposal.md"
            with patch("ncs_harness.load_settings", return_value=SimpleNamespace(db_path=db_path)):
                payload = self.run_harness_cli_json(
                    [
                        "api-unmatched-diagnosis",
                        "--limit",
                        "1",
                        "--out",
                        str(diagnosis_path),
                        "--markdown-out",
                        str(diagnosis_md),
                        "--proposal-out",
                        str(proposal_path),
                        "--proposal-markdown-out",
                        str(proposal_md),
                    ]
                )

            diagnosis = json.loads(diagnosis_path.read_text(encoding="utf-8"))
            proposal = json.loads(proposal_path.read_text(encoding="utf-8"))
            diagnosis_markdown = diagnosis_md.read_text(encoding="utf-8")
            proposal_markdown = proposal_md.read_text(encoding="utf-8")
            self.assertTrue(payload["ok"])
            self.assertEqual(payload["diagnosis_out_path"], str(diagnosis_path))
            self.assertEqual(payload["proposal_out_path"], str(proposal_path))
            self.assertEqual(diagnosis["summary"]["api_element_unmatched"]["total_rows"], 2)
            self.assertEqual(diagnosis["summary"]["api_element_unmatched"]["open_rows"], 1)
            self.assertEqual(proposal["dry_run_impact"]["resolved_api_element_unmatched_rows_removed"], 1)
            self.assertEqual(proposal["dry_run_impact"]["remaining_open_api_value_mismatch_rows"], 1)
            self.assertIn("API Unmatched Diagnosis", diagnosis_markdown)
            self.assertIn("API Unmatched Cleanup Proposal", proposal_markdown)
            self.assertTrue(diagnosis_path.exists())
            self.assertTrue(diagnosis_md.exists())
            self.assertTrue(proposal_path.exists())
            self.assertTrue(proposal_md.exists())

