            report = build_ksa_label_candidate_report(conn, sample_limit=5, collision_limit=5)
            seedpack = build_ksa_label_review_seedpack(conn, limit=5)
            conn.close()

            self.assertEqual(report["samples"][0]["raw_ksa_text"], source_text)
            self.assertIsNone(report["samples"][0]["atomic_ksa_text"])
            self.assertTrue(seedpack["rows"])
            self.assertEqual(seedpack["rows"][0]["raw_ksa_text"], source_text)
            self.assertIsNone(seedpack["rows"][0]["atomic_ksa_text"])
            self.assertEqual(seedpack["rows"][0]["raw_to_label_checked"], "")

            md_path = tmp_path / "ksa_label_report.md"
            jsonl_path = tmp_path / "ksa_label_seedpack.jsonl"
            csv_path = tmp_path / "ksa_label_seedpack.csv"
            write_ksa_label_candidate_report_markdown(report, md_path)
            write_ksa_label_review_seedpack_jsonl(seedpack, jsonl_path)
            write_ksa_label_review_seedpack_csv(seedpack, csv_path)

            for path, encoding in (
                (md_path, "utf-8"),
                (jsonl_path, "utf-8"),
                (csv_path, "utf-8-sig"),
            ):
                text = path.read_text(encoding=encoding)
                self.assertNotIn("\ufffd", text)
                self.assertIn(source_text, text)
                self.assertIn(label_text, text)

