    def test_default_aihr_dashboard_static_artifacts_prefer_session_local_dir(self) -> None:
        keys = [
            "NCS_AIHR_STATIC_ARTIFACT_DIR",
            "NCS_AIHR_READINESS_JSON_PATH",
            "NCS_HUMAN_REVIEW_SAFE_OPS_CHECKPOINT_JSON_PATH",
            "NCS_HUMAN_REVIEW_BACKLOG_JSON_PATH",
            "NCS_AIHR_AGENT_QUEUE_STATUS_JSON_PATH",
            "NCS_AIHR_AGENT_QUEUE_RUN_JSON_PATH",
        ]
        previous = {key: os.environ.get(key) for key in keys}
        with tempfile.TemporaryDirectory() as tmp:
            session_dir = Path(tmp) / "reports" / "overnight_sessions" / "readonly_refresh"
            session_dir.mkdir(parents=True)
            readiness = session_dir / "aihr_release_readiness_20260627_next.json"
            queue_status = session_dir / "aihr_agent_queue_status_20260627_next.json"
            queue_run = session_dir / "aihr_agent_queue_run_20260627_next.json"
            checkpoint = session_dir / "human_review_safe_ops_checkpoint_20260629_next.json"
            backlog = session_dir / "human_review_backlog_report_20260629_next.json"
            for path in (readiness, queue_status, queue_run, checkpoint, backlog):
                path.write_text("{}", encoding="utf-8")
            try:
                for key in keys:
                    os.environ.pop(key, None)
                os.environ["NCS_AIHR_READINESS_JSON_PATH"] = str(readiness)

                artifacts = default_aihr_dashboard_static_artifacts()

                self.assertEqual(artifacts["readiness_json"], readiness)
                self.assertEqual(artifacts["queue_status_json"], queue_status)
                self.assertEqual(artifacts["queue_run_json"], queue_run)
                self.assertEqual(artifacts["human_review_safe_ops_checkpoint_json"], checkpoint)
                self.assertEqual(artifacts["human_review_backlog_json"], backlog)
            finally:
                for key, value in previous.items():
                    if value is None:
                        os.environ.pop(key, None)
                    else:
                        os.environ[key] = value

    def test_verify_aihr_dashboard_cli_accepts_static_artifact_dir(self) -> None:
        previous_argv = sys.argv[:]
        stdout = io.StringIO()
        with tempfile.TemporaryDirectory() as tmp:
            static_dir = Path(tmp)
            queue_status = static_dir / "aihr_agent_queue_status_20260629.json"
            queue_status.write_text("{}", encoding="utf-8")
            sys.argv = [
                "ncs_harness.py",
                "verify-aihr-dashboard",
                "--base-url",
                "http://127.0.0.1:8765",
                "--static-artifact-dir",
                str(static_dir),
                "--single-plan-check",
            ]
            try:
                with (
                    patch(
                        "ncs_harness.verify_aihr_dashboard_surface",
                        return_value={"ok": True, "schema": "aihr_dashboard_surface_verification_v1"},
                    ) as verify_mock,
                    contextlib.redirect_stdout(stdout),
                ):
                    main()
            finally:
                sys.argv = previous_argv

        payload = json.loads(stdout.getvalue())
        self.assertTrue(payload["ok"])
        verify_mock.assert_called_once()
        static_artifacts = verify_mock.call_args.kwargs["static_artifact_paths"]
        self.assertEqual(static_artifacts["queue_status_json"], queue_status)

