            self.assertEqual(good_plan["raw_batch_count"], 68)
            self.assertTrue(good_plan["raw_batch_count_matches_batches"])
            self.assertEqual(good_plan["raw_unsafe_batch_count"], 0)
            self.assertTrue(good_plan["raw_unsafe_batch_count_matches_batches"])
