    def test_static_artifact_snapshot_flags_missing_or_stale_qualification_checkpoint_values(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "qualification_collection_coverage_plan_20260624.json"
            payload = sample_qualification_coverage_plan_report()
            payload["batches"][0]["command"] = (
                "python scripts\\ncs_harness.py collect-qualification-items "
                "--all-units --limit-units 100 --num-of-rows 50 "
                "--ncs006-checkpoint-path"
            )
            path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
            missing_snapshot = _static_artifact_snapshot(
                "qualification_collection_coverage_plan_json",
                path,
            )

            payload = sample_qualification_coverage_plan_report()
            payload["batches"][0]["command"] = payload["batches"][0]["command"].replace(
                "reports\\checkpoint_ncs006_element_api_status_20260630_current.json",
                "reports\\stale_checkpoint.json",
            )
            path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
            stale_snapshot = _static_artifact_snapshot(
                "qualification_collection_coverage_plan_json",
                path,
            )

            payload = sample_qualification_coverage_plan_report()
            absolute_checkpoint = ROOT / "reports" / "checkpoint_ncs006_element_api_status_20260630_current.json"
            payload["batches"][0]["command"] = payload["batches"][0]["command"].replace(
                "reports\\checkpoint_ncs006_element_api_status_20260630_current.json",
                str(absolute_checkpoint),
            )
            path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
            equivalent_path_snapshot = _static_artifact_snapshot(
                "qualification_collection_coverage_plan_json",
                path,
            )

        missing_plan = missing_snapshot["qualification_collection_coverage_plan"]
        stale_plan = stale_snapshot["qualification_collection_coverage_plan"]
        equivalent_path_plan = equivalent_path_snapshot["qualification_collection_coverage_plan"]
        self.assertEqual(missing_plan["unsafe_batch_count"], 68)
        self.assertFalse(missing_plan["batch_commands_have_ncs006_checkpoint_values"])
        self.assertFalse(missing_plan["batch_commands_checkpoint_values_match_plan"])
        self.assertEqual(stale_plan["unsafe_batch_count"], 68)
        self.assertTrue(stale_plan["batch_commands_have_ncs006_checkpoint_values"])
        self.assertFalse(stale_plan["batch_commands_checkpoint_values_match_plan"])
        self.assertEqual(stale_plan["batch_commands_unique_checkpoint_paths"], ["reports\\stale_checkpoint.json"])
        self.assertEqual(equivalent_path_plan["unsafe_batch_count"], 0)
        self.assertTrue(equivalent_path_plan["batch_commands_have_ncs006_checkpoint_values"])
        self.assertTrue(equivalent_path_plan["batch_commands_checkpoint_values_match_plan"])

