    def test_static_artifact_snapshot_requires_query_route_contract_audit_pass(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "query_route_contract_audit_20260624.json"
            payload = {
                "schema": "ncs_query_route_contract_audit_v1",
                "ok": True,
                "status": "pass",
                "status_update_allowed": False,
                "db_writes": False,
                "approval_claim": False,
                "case_count": 1,
                "pass_count": 1,
                "failure_count": 0,
                "rows": [
                    {
                        "name": "education_system_design",
                        "status": "pass",
                        "issues": [],
                    }
                ],
                "failure_summary": [],
            }

            path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
            good_snapshot = _static_artifact_snapshot(
                "query_route_contract_audit_json",
                path,
            )
            self.assertTrue(good_snapshot["query_route_contract_audit"]["contract_ok"])
            self.assertEqual(
                good_snapshot["query_route_contract_audit"]["row_count"],
                1,
            )

            bad_payload = dict(payload)
            bad_payload["status"] = "fail"
            bad_payload["failure_count"] = 1
            path.write_text(json.dumps(bad_payload, ensure_ascii=False), encoding="utf-8")
            bad_snapshot = _static_artifact_snapshot(
                "query_route_contract_audit_json",
                path,
            )
            self.assertFalse(bad_snapshot["query_route_contract_audit"]["contract_ok"])
            self.assertEqual(
                bad_snapshot["query_route_contract_audit"]["failure_count"],
                1,
            )

            bool_count_payload = dict(payload)
            bool_count_payload.update(
                {
                    "case_count": True,
                    "pass_count": True,
                    "failure_count": False,
                }
            )
            path.write_text(
                json.dumps(bool_count_payload, ensure_ascii=False),
                encoding="utf-8",
            )
            bool_count_snapshot = _static_artifact_snapshot(
                "query_route_contract_audit_json",
                path,
            )
            self.assertFalse(
                bool_count_snapshot["query_route_contract_audit"]["contract_ok"]
            )

            spoofed_row_payload = dict(payload)
            spoofed_row_payload["rows"] = [
                {
                    "name": "education_system_design",
                    "status": "fail",
                    "issues": ["tool_mismatch"],
                }
            ]
            path.write_text(
                json.dumps(spoofed_row_payload, ensure_ascii=False),
                encoding="utf-8",
            )
            spoofed_row_snapshot = _static_artifact_snapshot(
                "query_route_contract_audit_json",
                path,
            )
            spoofed_row_contract = spoofed_row_snapshot["query_route_contract_audit"]
            self.assertFalse(spoofed_row_contract["contract_ok"])
            self.assertEqual(spoofed_row_contract["failed_row_count"], 1)
            self.assertEqual(spoofed_row_contract["row_issue_count"], 1)

