    def test_public_demo_payload_strips_internal_operational_metadata(self) -> None:
        payload = {
            "ok": True,
            "view": "ncs_education_plan",
            "relation_id": 10,
            "created_at": "2026-06-17T00:00:00Z",
            "nested": {
                "updated_at": "2026-06-17T00:00:00Z",
                "review_status": "candidate",
                "current_career_path_review_status_counts": {"candidate": 2},
                "current_career_path_review_state_counts": {"human_reviewed": 1},
                "source_review_status": "candidate",
                "data_sources": ["internal"],
                "source_url_or_document": "file:///internal/hr/course.docx",
                "NCS_FOO_SERVICE_KEY": "SHOULD_NOT_RENDER",
                "state_note": "accepted and reviewed",
                "keep": "visible",
            },
        }

        public_payload = public_demo_payload(payload)
        text = json.dumps(public_payload, ensure_ascii=False)

        self.assertTrue(public_payload["ok"])
        self.assertEqual(public_payload["public_demo_schema"], "aihr_public_demo_v1")
        policy = public_payload["review_context_policy"]
        self.assertEqual(policy["schema"], "aihr_public_review_context_policy_v1")
        self.assertTrue(policy["review_only"])
        self.assertTrue(policy["non_scoring"])
        self.assertFalse(policy["approval_claim"])
        self.assertFalse(policy["db_writes"])
        self.assertFalse(policy["status_update_allowed"])
        self.assertFalse(policy["source_payload_exposed"])
        self.assertEqual(public_payload["nested"]["keep"], "visible")
        self.assertNotIn("relation_id", text)
        self.assertNotIn("created_at", text)
        self.assertNotIn("updated_at", text)
        self.assertNotIn("review_status", text)
        self.assertNotIn("current_career_path_review_status_counts", text)
        self.assertNotIn("current_career_path_review_state_counts", text)
        self.assertNotIn("source_review_status", text)
        self.assertNotIn("data_sources", text)
        self.assertNotIn("NCS_FOO_SERVICE_KEY", text)
        self.assertNotIn("SHOULD_NOT_RENDER", text)
        self.assertNotIn("accepted and reviewed", text)
        self.assertEqual(public_payload["nested"]["state_note"], "[REDACTED]")
        self.assertNotIn("source_url_or_document", public_payload["nested"])
        self.assertNotIn("file:///internal/hr/course.docx", text)

    def test_missing_task_locator_cli_exits_nonzero(self) -> None:
        previous_argv = sys.argv[:]
        stdout = io.StringIO()
        sys.argv = ["ncs_harness.py", "recommend-training-for-task"]
        try:
            with self.assertRaises(SystemExit) as raised:
                with contextlib.redirect_stdout(stdout):
                    main()
        finally:
            sys.argv = previous_argv

        payload = json.loads(stdout.getvalue())
        self.assertEqual(raised.exception.code, 1)
        self.assertFalse(payload["ok"])
        self.assertEqual(payload["error"]["code"], "missing_task_locator")

