    def test_queue_source_path_matcher_normalizes_relative_and_windows_paths(self) -> None:
        expected = "reports/aihr_agent_queue_20260624.json"
        self.assertTrue(
            _queue_source_path_matches(
                ".\\reports\\aihr_agent_queue_20260624.json",
                expected,
            )
        )
        self.assertTrue(
            _queue_source_path_matches(
                str(ROOT / "reports" / "aihr_agent_queue_20260624.json"),
                expected,
            )
        )
        self.assertFalse(
            _queue_source_path_matches(
                "C:\\other-workspace\\reports\\aihr_agent_queue_20260624.json",
                expected,
            )
        )
        self.assertFalse(
            _queue_source_path_matches(
                "C:\\workspace\\NCS_MCP\\reports\\aihr_agent_queue_stale.json",
                expected,
            )
        )

    def test_review_workflow_handoff_snapshot_rejects_unsafe_review_chain(self) -> None:
        payload = sample_aihr_review_workflow_handoff()
        payload["status_update_allowed"] = True
        payload["guardrails"]["source_payload_exposed"] = True
        payload["debug_copy_not_contract"] = {
            "blocked_automation_actions": [
                "auto_approve",
                "write_human_reviewed_accepted_or_reviewed",
                "treat_report_training_as_official_learning_module",
                "score_boost_from_report_or_derived_diagnostics",
            ]
        }
        payload["evidence_gap_triage"]["next_request_triage"]["review_surface_contract"] = {
            "blocked_automation_actions": [
                "auto_approve",
                "write_human_reviewed_accepted_or_reviewed",
                "treat_report_training_as_official_learning_module",
                "score_boost_from_report_or_derived_diagnostics",
            ]
        }
        payload["evidence_gap_triage"]["next_request_triage"]["unit_triage"][
            "review_surface_contract"
        ][
            "blocked_automation_actions"
        ] = ["auto_approve"]

        summary = _aihr_review_workflow_handoff_snapshot(payload)

        self.assertFalse(summary["contract_ok"])
        self.assertIn("root.status_update_allowed_not_false", summary["issues"])
        self.assertIn("guardrails.source_payload_exposed_not_false", summary["issues"])
        self.assertIn(
            "missing_blocked_action:write_human_reviewed_accepted_or_reviewed",
            summary["issues"],
        )
        self.assertIn(
            "missing_blocked_action:score_boost_from_report_or_derived_diagnostics",
            summary["issues"],
        )

