    def test_review_workflow_handoff_snapshot_requires_collection_policy_redaction(self) -> None:
        payload = sample_aihr_review_workflow_handoff()
        payload["official_learning_module_gap_audit"]["path"] = "reports/official_gap.json"
        payload["official_learning_module_gap_audit"]["collection_policy"] = {
            "full_scope_command": (
                "python scripts\\ncs_harness.py collect-study-modules --all-majors"
            ),
            "collect_study_modules_db_writes": True,
            "query_study_modules_db_writes": False,
            "collect_study_modules_effect": "writes learning-module rows",
            "scoped_lookup_rule": "Use query-study-modules for debugging only.",
        }

        summary = _aihr_review_workflow_handoff_snapshot(payload)

        self.assertFalse(summary["contract_ok"])
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.full_scope_command_exposed",
            summary["issues"],
        )
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.do_not_call_api_from_reviewer_artifact_not_true",
            summary["issues"],
        )
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.collect_study_modules_db_writes_exposed",
            summary["issues"],
        )
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.query_study_modules_db_writes_exposed",
            summary["issues"],
        )
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.collect_study_modules_effect_exposed",
            summary["issues"],
        )
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.forbidden_text_exposed:query-study-modules",
            summary["issues"],
        )

        payload["official_learning_module_gap_audit"]["collection_policy"] = {
            "legacy_diagnostic_collection": "out_of_band_operator_workflow_only",
            "full_scope_command_withheld": True,
            "do_not_call_api_from_reviewer_artifact": True,
            "separate_operator_workflow_required": True,
            "collection_command_operator_note": (
                "command withheld from reviewer artifact; do not run collection from this review artifact."
            ),
            "scoped_lookup_rule": (
                "Use a separate operator-controlled official EDU lookup workflow "
                "for single-unit debug."
            ),
        }
        summary = _aihr_review_workflow_handoff_snapshot(payload)

        self.assertTrue(summary["contract_ok"], summary["issues"])
        self.assertNotIn(
            "collect_study_modules_db_writes",
            payload["official_learning_module_gap_audit"]["collection_policy"],
        )
        self.assertNotIn(
            "query_study_modules_db_writes",
            payload["official_learning_module_gap_audit"]["collection_policy"],
        )
        self.assertNotIn(
            "collect_study_modules_effect",
            payload["official_learning_module_gap_audit"]["collection_policy"],
        )

        payload["official_learning_module_gap_audit"]["collection_policy"] = {
            "legacy_diagnostic_collection": "out_of_band_operator_workflow_only",
            "full_scope_command_withheld": True,
            "do_not_call_api_from_reviewer_artifact": True,
            "separate_operator_workflow_required": True,
            "scoped_lookup_rule": (
                "Use a separate operator-controlled official EDU lookup workflow "
                "for single-unit debug."
            ),
        }
        summary = _aihr_review_workflow_handoff_snapshot(payload)
        self.assertFalse(summary["contract_ok"])
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.collection_command_operator_note_missing",
            summary["issues"],
        )

        payload["official_learning_module_gap_audit"]["collection_policy"][
            "collection_command_operator_note"
        ] = "operator-only collection note"
        summary = _aihr_review_workflow_handoff_snapshot(payload)
        self.assertFalse(summary["contract_ok"])
        self.assertIn(
            "official_learning_module_gap_audit.collection_policy.collection_command_operator_note_missing_withheld_marker",
            summary["issues"],
        )

