    def test_aihr_reviewer_artifact_staleness_audit_flags_stale_surfaces(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            stale_handoff_path = tmp_path / "renamed_reviewer_handoff.json"
            stale_packet_index_md_path = (
                tmp_path / "aihr_plan_review_packet_index_20260701.md"
            )
            payload = sample_aihr_review_workflow_handoff()
            payload["ok"] = True
            payload["reviewer_start_here"]["ordered_steps"] = [
                {
                    "order": 99,
                    "label": "Review provenance reconfirmation packet",
                    "path": "reports/human_review_provenance_reconfirmation_packet_20260630.html",
                }
            ]
            payload["official_learning_module_gap_audit"]["path"] = (
                "reports/official_gap.json"
            )
            payload["official_learning_module_gap_audit"]["collection_policy"] = {
                "full_scope_command": (
                    "python scripts\\ncs_harness.py collect-study-modules --all-majors"
                )
            }
            stale_handoff_path.write_text(
                json.dumps(payload, ensure_ascii=False),
                encoding="utf-8",
            )
            stale_packet_index_md_path.write_text(
                "- collection_full_scope_command: python scripts\\ncs_harness.py collect-study-modules --all-majors\n",
                encoding="utf-8",
            )
            report = build_aihr_reviewer_artifact_staleness_audit(
                [stale_handoff_path, stale_packet_index_md_path]
            )
            md_out = tmp_path / "audit.md"
            write_aihr_reviewer_artifact_staleness_audit_markdown(report, md_out)
            markdown = md_out.read_text(encoding="utf-8")

        self.assertFalse(report["ok"])
        finding_codes = {finding["code"] for finding in report["findings"]}
        self.assertIn("reviewer_artifact_collection_command_exposed", finding_codes)
        self.assertIn("reviewer_artifact_forbidden_text_exposed", finding_codes)
        self.assertIn("reviewer_workflow_handoff_contract_failed", finding_codes)
        self.assertIn(
            "reviewer_artifact_self_reports_ok_despite_findings",
            finding_codes,
        )
        self.assertIn("status_update_allowed: false", markdown)
        self.assertIn("db_writes: false", markdown)
        self.assertNotIn("collect-study-modules --all-majors", markdown)
        self.assertNotIn("collection_full_scope_command", markdown)
        self.assertNotIn("full_scope_command", markdown)

