    def test_audit_aihr_reviewer_artifacts_cli_writes_report_and_fails_on_stale_packet_index(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            packet_index_path = tmp_path / "aihr_plan_review_packet_index_20260701.json"
            stale_markdown_path = tmp_path / "aihr_plan_review_packet_index_20260701.md"
            out_path = tmp_path / "staleness_audit.json"
            md_out = tmp_path / "staleness_audit.md"
            packet_index_path.write_text(
                json.dumps(
                    {
                        "schema": "aihr_plan_review_packet_index_v1",
                        "ok": True,
                        "blocker_count": 1,
                        "counts": {
                            "link_count": 1,
                            "missing_or_empty_link_count": 1,
                            "source_payload_exposed_count": 0,
                        },
                        "links": [
                            {
                                "label": "next_request",
                                "path": str(tmp_path / "missing_next_request.html"),
                                "exists": True,
                                "non_empty": True,
                                "source_payload_exposed": False,
                            }
                        ],
                    },
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
            stale_markdown_path.write_text(
                "- collection_full_scope_command: python scripts\\ncs_harness.py collect-study-modules --all-majors\n",
                encoding="utf-8",
            )
            argv = [
                "ncs_harness.py",
                "audit-aihr-reviewer-artifacts",
                "--artifact",
                str(packet_index_path),
                "--artifact",
                str(stale_markdown_path),
                "--out",
                str(out_path),
                "--markdown-out",
                str(md_out),
            ]
            stdout = io.StringIO()
            with patch.object(sys, "argv", argv), contextlib.redirect_stdout(stdout):
                with self.assertRaises(SystemExit) as raised:
                    main()
            report = json.loads(out_path.read_text(encoding="utf-8"))
            md_exists = md_out.exists()
            markdown = md_out.read_text(encoding="utf-8")
            stdout_payload = json.loads(stdout.getvalue())

        self.assertEqual(raised.exception.code, 1)
        self.assertFalse(report["ok"])
        self.assertTrue(md_exists)
        self.assertFalse(stdout_payload["ok"])
        self.assertEqual(stdout_payload["out_path"], str(out_path))
        self.assertTrue(stdout_payload["full_findings_written_to_file"])
        self.assertNotIn("findings", stdout_payload)
        self.assertNotIn("artifacts", stdout_payload)
        self.assertIn("reviewer_packet_index_contract_failed", stdout.getvalue())
        self.assertIn("reviewer_artifact_forbidden_text_exposed", stdout.getvalue())
        self.assertIn("collect-study-modules --all-majors", json.dumps(report, ensure_ascii=False))
        self.assertNotIn("collect-study-modules --all-majors", stdout.getvalue())
        self.assertNotIn("collect-study-modules --all-majors", markdown)
        self.assertNotIn("collection_full_scope_command", markdown)
        self.assertNotIn("full_scope_command", markdown)
        self.assertIn("reviewer_packet_index_contract_failed", markdown)

