    def test_static_artifact_snapshot_flags_local_database_path_leaks(self) -> None:
        payload = {
            "schema": "aihr_release_readiness_v1",
            "ok": True,
            "agent_work_queue_path": "reports/aihr_agent_queue_20260624.json",
            "db_path": "C:/workspace/NCS_MCP/data/processed/ncs.db",
            "dashboard_surface_contract": {
                "artifact": {"content_sha256": "sha256:" + ("0" * 64)}
            },
            "artifact_lineage_contract": {
                "dashboard_verification_content_sha256": "sha256:" + ("1" * 64)
            },
        }
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "readiness.json"
            path.write_text(
                json.dumps(payload, ensure_ascii=False),
                encoding="utf-8",
            )

            snapshot = _static_artifact_snapshot("readiness_json", path)

        self.assertTrue(snapshot["local_path_exposed"])
        self.assertIn("configured_database_reference", snapshot["local_path_markers"])
        self.assertIn("configured_workspace_reference", snapshot["local_path_markers"])
        self.assertEqual(
            snapshot["cycle_safe_content_sha256"],
            _release_readiness_cycle_safe_sha256(payload),
        )
        self.assertEqual(
            snapshot["cycle_safe_hash_excluded_fields"],
            [
                "artifact_lineage_contract",
                "cycle_safe_content_sha256",
                "cycle_safe_hash_excluded_fields",
                "sha256_scope",
                "dashboard_surface_contract.artifact.mtime_utc",
                "dashboard_surface_contract.**.mtime_utc",
                "dashboard_surface_contract.**.size_bytes",
                "dashboard_surface_contract.**.content_sha256",
                "dashboard_surface_contract.**.cycle_safe_content_sha256",
                "dashboard_surface_contract.**.human_review_backlog.contract_ok",
                "dashboard_surface_contract.**.human_review_backlog.source_hash_contract_ok",
                "dashboard_surface_contract.**.human_review_backlog.source_hash_revalidation_ok",
                "dashboard_surface_contract.**.human_review_backlog.source_hash_revalidation_checked_count",
                "dashboard_surface_contract.**.human_review_backlog.source_hash_revalidation_mismatch_count",
                "dashboard_surface_contract.**.human_review_backlog.source_hash_revalidation_issues",
            ],
        )

