        self.assertTrue(any("authKey" in issue for issue in issues))
        self.assertTrue(any("raw_payload" in issue for issue in issues))
        self.assertTrue(any("stderr_tail_sensitive_markers" in issue for issue in issues))
        self.assertTrue(any("Authorization" in issue for issue in issues))
        self.assertTrue(any("apiKey" in issue for issue in issues))
        self.assertTrue(any("certKey" in issue for issue in issues))

