        self.assertEqual(payload["schema"], "ncs_ksa_term_review_operator_packet_v1")
        self.assertEqual(payload["out"], str(out_path))
        self.assertEqual(payload["workflow_manifest"], str(workflow_path))
        self.assertEqual(payload["decision_audit"], str(decision_audit_path))
        self.assertEqual(payload["action_plan"], str(action_plan_path))
        self.assertEqual(payload["readiness"], str(readiness_path))
        self.assertEqual(payload["minimal_review_csv"], str(slice_csv_path))
        self.assertEqual(payload["concept_review_group_count"], 2)
        self.assertEqual(payload["pending_decision_count"], 2)
        self.assertTrue(payload["ready_for_minimal_human_review"])
        self.assertFalse(payload["ready_for_guarded_action_plan_review"])
        self.assertFalse(payload["status_update_allowed"])
        self.assertFalse(payload["db_writes"])
        self.assertFalse(payload["approval_claim"])
        self.assertFalse(payload["source_payload_exposed"])
        self.assertEqual(packet["schema"], "ncs_ksa_term_review_operator_packet_v1")
        self.assertFalse(packet["status_update_allowed"])
        self.assertFalse(packet["db_writes"])
        self.assertFalse(packet["approval_claim"])
        self.assertFalse(packet["trusted_status_write_allowed"])
        self.assertFalse(packet["raw_source_mutation_allowed"])
        self.assertFalse(packet["source_payload_exposed"])
        self.assertFalse(packet["safety_contract"]["status_update_allowed"])
        self.assertFalse(packet["safety_contract"]["db_writes"])
        self.assertFalse(packet["safety_contract"]["approval_claim"])
        self.assertFalse(packet["safety_contract"]["source_payload_exposed"])
        self.assertEqual(
            packet["safety_contract"]["forbidden_automatic_statuses"],
            ["human_reviewed", "accepted", "reviewed"],
        )
        self.assertEqual(packet["workflow_summary"]["concept_review_group_count"], 2)
        self.assertEqual(packet["workflow_summary"]["decision_blank_count"], 2)
        self.assertEqual(packet["readiness_summary"]["pending_decision_count"], 2)
        self.assertEqual(packet["readiness_summary"]["action_count"], 0)
        self.assertEqual(
            packet["readiness_summary"]["next_step"],
            "fill_minimal_review_csv_decisions_for_first_review_queue",
        )
        self.assertTrue(workflow["ok"])
        self.assertEqual(workflow["summary"]["concept_review_csv_record_count"], 2)
        self.assertEqual(workflow["summary"]["decision_blank_count"], 2)
        self.assertEqual(decision_audit["pending_decision_count"], 2)
        self.assertEqual(decision_audit["completed_decision_count"], 0)
        self.assertEqual(action_plan["action_count"], 0)
        self.assertTrue(readiness["ready_for_minimal_human_review"])
        self.assertFalse(readiness["ready_for_guarded_action_plan_review"])
        self.assertEqual(len(slice_csv_rows), 2)
        self.assertTrue(all(row["decision"] == "" for row in slice_csv_rows))
        self.assertTrue(all(row["reviewer_id"] == "" for row in slice_csv_rows))
        self.assertTrue(all(row["reviewed_at"] == "" for row in slice_csv_rows))
        self.assertTrue(all(row["rationale"] == "" for row in slice_csv_rows))
        self.assertTrue(all(row["status_update_allowed"] == "False" for row in slice_csv_rows))
        self.assertNotIn('"source_payload":', packet_text)
        self.assertNotIn("raw_source_payload_value", packet_text)
        self.assertNotIn("concept_review_groups", packet_text)
        self.assertIn("KSA Term Review Operator Packet", packet_markdown)

