    def test_qualification_coverage_plan_reports_raw_batch_guard_summary(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            db_path = Path(tmp) / "ncs.db"
            conn = connect(db_path)
            initialize_database(conn)
            timestamp = now_utc()
            conn.execute(
                """
                INSERT INTO classifications(
                    major_code, major_name, middle_code, middle_name,
                    small_code, small_name, sub_code, sub_name
                ) VALUES ('02', 'Management', '02', 'HR', '02', 'HRM', '01', 'HR Planning')
                """
            )
            classification_id = conn.execute(
                "SELECT classification_id FROM classifications"
            ).fetchone()["classification_id"]
            for index in range(1, 4):
                conn.execute(
                    """
                    INSERT INTO competency_units(
                        unit_code, base_unit_code, unit_version, unit_name_raw,
                        unit_level_raw, classification_id, api_match_status,
                        created_at, updated_at
                    ) VALUES (?, ?, '23v3', ?, '4', ?, 'matched', ?, ?)
                    """,
                    (
                        f"020202010{index}_23v3",
                        f"020202010{index}",
                        f"HR planning unit {index}",
                        classification_id,
                        timestamp,
                        timestamp,
                    ),
                )
            conn.execute(
                """
                INSERT INTO ncs_qualification_collection_status(
                    unit_code, collection_status, rows_collected, pages_processed,
                    updated_at
                ) VALUES ('0202020101_23v3', 'collected', 1, 1, ?)
                """,
                (timestamp,),
            )
            conn.commit()

            report = qualification_collection_coverage_plan(
                conn,
                target_ratio=1.0,
                batch_size=1,
                checkpoint_path=Path("reports") / "checkpoint.json",
            )
            conn.close()

        self.assertEqual(report["schema"], "ncs_qualification_collection_coverage_plan_v1")
        self.assertEqual(report["batch_count"], 2)
        self.assertEqual(report["target_state"]["estimated_batch_count"], 2)
        self.assertEqual(report["unsafe_batch_count"], 0)
        self.assertEqual(report["unsafe_batches"], [])
        self.assertEqual(report["checkpoint_path"], "reports\\checkpoint.json")
        self.assertTrue(report["batch_commands_have_ncs006_checkpoint_values"])
        self.assertTrue(report["batch_commands_checkpoint_values_match_plan"])
        self.assertEqual(report["batch_commands_unique_checkpoint_paths"], ["reports\\checkpoint.json"])
        self.assertFalse(report["automatic_collection_allowed_now"])
        self.assertTrue(report["operator_timed_guarded_api_commands_only"])
        for batch in report["batches"]:
            self.assertEqual(batch["command_role"], "operator_timed_guarded_api_collection")
            self.assertFalse(batch["auto_runnable"])
            self.assertFalse(batch["automatic_queue_execution_allowed"])
            self.assertFalse(batch["execution_authorized"])
            self.assertTrue(batch["do_not_execute_from_report"])
            self.assertTrue(batch["not_queue_item"])
            self.assertTrue(batch["requires_operator_ticket"])
            self.assertTrue(batch["requires_operator_timing"])
            self.assertIn("--ncs006-checkpoint-path reports\\checkpoint.json", batch["command"])

