    def _write_operator_packet_integrity_fixture(self, root: Path) -> dict[str, Path]:
        reports = root / "reports"
        reports.mkdir(parents=True, exist_ok=True)
        packet = reports / "packet.json"
        packet.write_text("{}\n", encoding="utf-8")
        packet_hash = "sha256:" + hashlib.sha256(packet.read_bytes()).hexdigest()

        def write_json_with_md(
            path: Path,
            schema: str,
            *,
            source_paths: dict[str, str] | None = None,
            source_hashes: dict[str, str | None] | None = None,
            extra: dict | None = None,
        ) -> None:
            payload = {
                "schema": schema,
                "generated_at": "2026-07-12T03:00:00+00:00",
                "ok": True,
                "report_only": True,
                "status_update_allowed": False,
                "db_writes": False,
                "api_calls": False,
                "approval_claim": False,
                "human_decision_required": True,
                "forbidden_automatic_statuses": [
                    "human_reviewed",
                    "accepted",
                    "reviewed",
                ],
            }
            if source_paths is not None:
                payload["source_paths"] = source_paths
                payload["source_hashes"] = source_hashes or {}
            if extra:
                payload.update(extra)
            path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            path.with_suffix(".md").write_text("# sidecar\n", encoding="utf-8")

        def write_decision_csv(path: Path) -> None:
            with path.open("w", encoding="utf-8-sig", newline="") as handle:
                writer = csv.DictWriter(
                    handle,
                    fieldnames=[
                        "id",
                        "decision",
                        "reviewer_id",
                        "reviewed_at",
                        "rationale",
                        "status_update_allowed",
                        "db_writes",
                        "approval_claim",
                    ],
                )
                writer.writeheader()
                writer.writerow(
                    {
                        "id": "1",
                        "status_update_allowed": "false",
                        "db_writes": "false",
                        "approval_claim": "false",
                    }
                )

        concept = reports / "concept.csv"
        blocker = reports / "blocker.csv"
        decision_csv = reports / "decision.csv"
        for path in (concept, blocker, decision_csv):
            write_decision_csv(path)

        qualification_csv = reports / "qualification.csv"
        with qualification_csv.open("w", encoding="utf-8-sig", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=["wave", "batch_count"])
            writer.writeheader()
            writer.writerow({"wave": "pilot", "batch_count": "3"})

        crosswalk_csv = reports / "transition_provenance_operator_crosswalk_20260712_10h.csv"
        with crosswalk_csv.open("w", encoding="utf-8-sig", newline="") as handle:
            writer = csv.DictWriter(
                handle,
                fieldnames=[
                    "scenario_id",
                    "decision_sheet_order",
                    "operator_source_decision_packet_ref",
                    "operator_source_artifact_hash",
                    "operator_decision_fields_blank",
                    "operator_guard_fields_false",
                ],
            )
            writer.writeheader()
            writer.writerow(
                {
                    "scenario_id": "3",
                    "decision_sheet_order": "24",
                    "operator_source_decision_packet_ref": "reports/packet.json#order:24",
                    "operator_source_artifact_hash": packet_hash,
                    "operator_decision_fields_blank": "true",
                    "operator_guard_fields_false": "true",
                }
            )

        support = reports / "support.json"
        support.write_text("{}\n", encoding="utf-8")
        queue_json = reports / "queue.json"
        queue_audit_json = reports / "queue_audit.json"
        crosswalk_json = reports / "transition_provenance_operator_crosswalk_20260712_10h.json"
        crosswalk_audit_json = reports / "transition_provenance_operator_crosswalk_audit_20260712_10h.json"
        decision_json = reports / "decision.json"
        decision_audit_json = reports / "decision_audit.json"
        qualification_json = reports / "qualification.json"
        transition_gap_json = reports / "transition_gap.json"
        next_actions_json = reports / "next_actions.json"
        write_json_with_md(
            queue_json,
            "aihr_blocker_reduction_operator_sprint_queue_v1",
            extra={
                "queue": [
                    {
                        "sprint_id": "S1-transition-provenance-crosswalk",
                        "open_first": "reports/transition_provenance_operator_crosswalk_20260712_10h.csv",
                    }
                ]
            },
        )
        write_json_with_md(queue_audit_json, "aihr_blocker_reduction_operator_sprint_queue_audit_v1")
        write_json_with_md(
            crosswalk_json,
            "transition_provenance_operator_crosswalk_v1",
            source_paths={"support": "reports/support.json"},
            source_hashes={
                "support": "sha256:" + hashlib.sha256(support.read_bytes()).hexdigest(),
            },
        )
        write_json_with_md(crosswalk_audit_json, "transition_provenance_operator_crosswalk_audit_v1")
        write_json_with_md(decision_json, "aihr_provenance_reconfirmation_decision_sheet_v1")
        write_json_with_md(decision_audit_json, "aihr_provenance_reconfirmation_decision_audit_v1")
        write_json_with_md(qualification_json, "qualification_guarded_batch_operator_decision_v1")
        write_json_with_md(transition_gap_json, "transition_trusted_scenario_provenance_gap_v1")
        write_json_with_md(
            next_actions_json,
            "aihr_operator_next_actions_v3",
            source_paths={
                "blocker_reduction_sprint_queue": "reports/queue.json",
                "blocker_reduction_sprint_queue_audit": "reports/queue_audit.json",
                "transition_provenance_crosswalk": "reports/transition_provenance_operator_crosswalk_20260712_10h.json",
                "transition_provenance_crosswalk_csv": "reports/transition_provenance_operator_crosswalk_20260712_10h.csv",
                "transition_provenance_crosswalk_audit": "reports/transition_provenance_operator_crosswalk_audit_20260712_10h.json",
            },
            source_hashes={
                "blocker_reduction_sprint_queue": "sha256:"
                + hashlib.sha256(queue_json.read_bytes()).hexdigest(),
                "blocker_reduction_sprint_queue_audit": "sha256:"
                + hashlib.sha256(queue_audit_json.read_bytes()).hexdigest(),
                "transition_provenance_crosswalk": "sha256:"
                + hashlib.sha256(crosswalk_json.read_bytes()).hexdigest(),
                "transition_provenance_crosswalk_csv": "sha256:"
                + hashlib.sha256(crosswalk_csv.read_bytes()).hexdigest(),
                "transition_provenance_crosswalk_audit": "sha256:"
                + hashlib.sha256(crosswalk_audit_json.read_bytes()).hexdigest(),
            },
            extra={
                "actions": [
                    {
                        "id": "transition_eval:trusted_scenarios",
                        "open_first": "reports/transition_provenance_operator_crosswalk_20260712_10h.csv",
                        "artifacts_to_open": [
                            "reports/transition_provenance_operator_crosswalk_20260712_10h.csv"
                        ],
                    }
                ]
            },
        )
        return {
            "concept": concept,
            "blocker": blocker,
            "decision_csv": decision_csv,
            "crosswalk_csv": crosswalk_csv,
            "qualification_csv": qualification_csv,
            "decision_json": decision_json,
            "decision_audit_json": decision_audit_json,
            "qualification_json": qualification_json,
            "transition_gap_json": transition_gap_json,
            "crosswalk_json": crosswalk_json,
            "crosswalk_audit_json": crosswalk_audit_json,
            "queue_json": queue_json,
            "queue_audit_json": queue_audit_json,
            "next_actions_json": next_actions_json,
            "packet": packet,
        }

