    def test_run_aihr_plan_demo_cli_generates_json_and_html(self) -> None:
        class DummyConn:
            def close(self) -> None:
                pass

        previous_argv = sys.argv[:]
        stdout = io.StringIO()
        full_result = {"ok": True, "full": True}
        plan_results = [
            {"ok": True, "view": "ncs_education_plan", "plan_objective": "baseline"},
            {"ok": True, "view": "ncs_education_plan", "plan_objective": "alias"},
        ]
        with tempfile.TemporaryDirectory() as tmp:
            out_dir = Path(tmp)
            sidecar_path = out_dir / "review_context.json"
            sidecar_path.write_text(
                json.dumps(
                    {
                        "schema": "aihr_plan_review_unit_evidence_packet_v1",
                        "units": [],
                    }
                ),
                encoding="utf-8",
            )
            sys.argv = [
                "ncs_harness.py",
                "run-aihr-plan-demo",
                "--out-dir",
                str(out_dir),
                "--base-name",
                "demo",
                "--review-context",
                str(sidecar_path),
                "--preferred-facility",
                "전산강의실",
            ]
            try:
                with (
                    patch("ncs_harness.load_settings", return_value=SimpleNamespace(db_path=Path("ncs.db"))),
                    patch("ncs_harness._connect_readonly_sqlite", return_value=DummyConn()) as readonly_mock,
                    patch("ncs_harness.connect") as connect_mock,
                    patch("ncs_harness.initialize_database") as initialize_mock,
                    patch("ncs_harness.recommend_training_transition", return_value=full_result) as recommend_mock,
                    patch(
                        "ncs_harness.compact_ncs_education_plan_response",
                        side_effect=plan_results,
                    ) as plan_mock,
                    patch("render_aihr_plan_demo.render", return_value="<html>demo</html>") as render_mock,
                    contextlib.redirect_stdout(stdout),
                ):
                    main()
            finally:
                sys.argv = previous_argv

            response = json.loads(stdout.getvalue())
            baseline = out_dir / "demo.json"
            alias = out_dir / "demo_alias.json"
            html_path = out_dir / "demo.html"

            self.assertTrue(response["ok"])
            self.assertEqual(len(response["json_artifacts"]), 2)
            self.assertEqual(len(response["internal_json_artifacts"]), 2)
            self.assertEqual(response["review_contexts"], [str(sidecar_path)])
            self.assertTrue(baseline.exists())
            self.assertTrue(alias.exists())
            self.assertTrue((out_dir / "demo_internal.json").exists())
            self.assertTrue((out_dir / "demo_alias_internal.json").exists())
            self.assertEqual(
                json.loads(baseline.read_text(encoding="utf-8"))["public_demo_schema"],
                "aihr_public_demo_v1",
            )
            baseline_internal = json.loads((out_dir / "demo_internal.json").read_text(encoding="utf-8"))
            alias_internal = json.loads((out_dir / "demo_alias_internal.json").read_text(encoding="utf-8"))
            self.assertEqual(
                baseline_internal["query_route"]["tool"],
                "plan_ncs_education_path",
            )
            self.assertEqual(
                alias_internal["query_route"]["tool"],
                "plan_ncs_education_path",
            )
            self.assertEqual(baseline_internal["route_contract_schema"], "ncs_query_route_v1")
            self.assertTrue(baseline_internal["route_fingerprint"])
            self.assertEqual(html_path.read_text(encoding="utf-8"), "<html>demo</html>")
        readonly_mock.assert_called_once_with(Path("ncs.db"))
        connect_mock.assert_not_called()
        initialize_mock.assert_not_called()
        self.assertEqual(recommend_mock.call_count, 2)
        self.assertEqual(plan_mock.call_count, 2)
        self.assertFalse(recommend_mock.call_args_list[0].kwargs["save"])
        self.assertEqual(recommend_mock.call_args_list[0].kwargs["preferred_facilities"], ["전산강의실"])
        self.assertEqual(recommend_mock.call_args_list[1].kwargs["preferred_facilities"], ["전산강의실"])
        render_mock.assert_called_once_with(
            [baseline, alias],
            review_context_paths=[sidecar_path],
        )

    def test_run_aihr_plan_demo_cli_fails_before_artifacts_when_route_contract_missing(self) -> None:
        class DummyConn:
            def close(self) -> None:
                pass

        previous_argv = sys.argv[:]
        stdout = io.StringIO()
        with tempfile.TemporaryDirectory() as tmp:
            out_dir = Path(tmp)
            sys.argv = [
                "ncs_harness.py",
                "run-aihr-plan-demo",
                "--out-dir",
                str(out_dir),
                "--base-name",
                "demo",
            ]
            try:
                with (
                    patch("ncs_harness.load_settings", return_value=SimpleNamespace(db_path=Path("ncs.db"))),
                    patch("ncs_harness._connect_readonly_sqlite", return_value=DummyConn()) as readonly_mock,
                    patch("ncs_harness._aihr_public_route_evidence", return_value={"tool": "plan_ncs_education_path"}),
                    patch("ncs_harness.recommend_training_transition") as recommend_mock,
                    patch("ncs_harness.compact_ncs_education_plan_response") as plan_mock,
                    patch("render_aihr_plan_demo.render") as render_mock,
                    contextlib.redirect_stdout(stdout),
                    self.assertRaises(SystemExit) as raised,
                ):
                    main()
            finally:
                sys.argv = previous_argv

            self.assertEqual(raised.exception.code, 1)
            payload = json.loads(stdout.getvalue())
            self.assertFalse(payload["ok"])
            self.assertEqual(payload["error"]["code"], "missing_query_route_contract")
            self.assertEqual(payload["case"], "baseline")
            self.assertFalse((out_dir / "demo.json").exists())
            self.assertFalse((out_dir / "demo_internal.json").exists())
            self.assertFalse((out_dir / "demo.html").exists())
        readonly_mock.assert_called_once_with(Path("ncs.db"))
        recommend_mock.assert_not_called()
        plan_mock.assert_not_called()
        render_mock.assert_not_called()

    def test_export_chatgpt_evaluation_package_redacts_path_fields(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root / "reports").mkdir()
            (root / "README.md").write_text("readme", encoding="utf-8")
            (root / "reports" / "safe.json").write_text(
                json.dumps(
                    {
                        "pdf_path": "data/raw/module.pdf",
                        "nested": [{"txt_path": "data/processed/learning_module_ocr/card.txt"}],
                        "meta_path": None,
                    }
                ),
                encoding="utf-8",
            )
            out = root / "package.zip"

            result = export_chatgpt_evaluation_package(
                out,
                root=root,
                files=("README.md", "reports/safe.json"),
            )

            self.assertTrue(result["ok"], result)
            self.assertEqual(result["entry_count"], 3)
            with zipfile.ZipFile(out) as archive:
                names = set(archive.namelist())
                self.assertEqual(names, {"README.md", "reports/safe.json", "README_EVALUATION_PACKAGE.txt"})
                payload = json.loads(archive.read("reports/safe.json").decode("utf-8"))
            self.assertEqual(payload["pdf_path"], "[REDACTED_PATH]")
            self.assertEqual(payload["nested"][0]["txt_path"], "[REDACTED_PATH]")
            self.assertIsNone(payload["meta_path"])
            self.assertNotIn("data/raw", json.dumps(payload))

    def test_export_chatgpt_evaluation_package_rejects_forbidden_entries(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root / "README.md").write_text("readme", encoding="utf-8")
            out = root / "package.zip"

            result = export_chatgpt_evaluation_package(
                out,
                root=root,
                files=("README.md", "data/raw/source.pdf", "reports/overnight_sessions/session.jsonl"),
            )

            self.assertFalse(result["ok"])
            self.assertEqual(result["forbidden"]["data/raw/source.pdf"], "data_path_forbidden")
            self.assertEqual(
                result["forbidden"]["reports/overnight_sessions/session.jsonl"],
                "session_log_forbidden",
            )
            with zipfile.ZipFile(out) as archive:
                self.assertEqual(set(archive.namelist()), {"README.md", "README_EVALUATION_PACKAGE.txt"})

