    def test_aihr_learning_module_basis_reports_non_official_gap_diagnostics(self) -> None:
        conn = sqlite3.connect(":memory:")
        conn.row_factory = sqlite3.Row
        try:
            conn.executescript(
                """
                CREATE TABLE competency_units(
                    unit_code TEXT PRIMARY KEY,
                    base_unit_code TEXT,
                    unit_name_raw TEXT,
                    classification_id INTEGER
                );
                CREATE TABLE ncs_learning_modules(
                    learn_module_seq TEXT PRIMARY KEY,
                    learn_module_name TEXT
                );
                CREATE TABLE learning_module_unit_links(
                    link_id INTEGER PRIMARY KEY,
                    learn_module_seq TEXT,
                    unit_code TEXT,
                    link_method TEXT,
                    confidence_score REAL,
                    evidence_text TEXT,
                    review_status TEXT
                );
                """
            )
            conn.execute(
                "INSERT INTO competency_units VALUES ('0202020101_23v3', '0202020101', 'HR planning', 1)"
            )
            conn.execute(
                "INSERT INTO ncs_learning_modules VALUES ('NCS-DERIVED-0202020101_23v3', 'Derived HR plan')"
            )
            conn.execute(
                "INSERT INTO ncs_learning_modules VALUES ('REPORT-TRAINING-HR-1', 'Report HR course')"
            )
            conn.execute(
                """
                INSERT INTO learning_module_unit_links VALUES
                (1, 'NCS-DERIVED-0202020101_23v3', '0202020101_23v3',
                 'ncs_derived_plan_unit', 0.8, 'Generated plan maps to HR unit.', 'auto_linked')
                """
            )
            conn.execute(
                """
                INSERT INTO learning_module_unit_links VALUES
                (2, 'REPORT-TRAINING-HR-1', '0202020101_23v3',
                 'report_training_course_unit', 0.7, 'Report course maps to HR unit.', 'reviewed')
                """
            )
            conn.commit()

            basis = _aihr_learning_module_review_basis(
                conn,
                ncs_cl_cd="0202020101",
                limit=5,
            )
            diagnostic_basis = _aihr_non_official_diagnostic_review_basis(
                conn,
                ncs_cl_cd="0202020101",
                limit=5,
            )
            sources = _aihr_review_basis_sources(basis, {}, diagnostic_basis)
            display = _aihr_review_evidence_display_value(
                "learning_module_review_basis",
                basis,
            )
            diagnostic_display = _aihr_review_evidence_display_value(
                "non_official_diagnostic_basis",
                diagnostic_basis,
            )
            source_display = _aihr_review_evidence_display_value(
                "review_basis_sources",
                sources,
            )
            markdown = "\n".join(
                _aihr_review_basis_markdown_rows(
                    {
                        "learning_module_review_basis": basis,
                        "non_official_diagnostic_basis": diagnostic_basis,
                    }
                )
            )
            html = "\n".join(
                _aihr_review_basis_html_rows(
                    {
                        "learning_module_review_basis": basis,
                        "non_official_diagnostic_basis": diagnostic_basis,
                    }
                )
            )
        finally:
            conn.close()

        self.assertEqual(basis["status"], "missing")
        self.assertEqual(basis["official_module_count"], 0)
        self.assertEqual(basis["trusted_link_count"], 0)
        self.assertEqual(basis["review_status_counts"], {})
        self.assertEqual(
            basis["gap_reason"],
            "no_official_direct_learning_module_link_but_report_or_derived_basis_exists",
        )
        self.assertEqual(
            basis["direct_non_official_counts"],
            {"ncs_derived_learning_plan": 1, "report_training_course": 1},
        )
        self.assertNotIn("direct_non_official_samples", basis)
        self.assertEqual(diagnostic_basis["status"], "diagnostic_basis_visible")
        self.assertEqual(
            diagnostic_basis["direct_non_official_counts"],
            {"ncs_derived_learning_plan": 1, "report_training_course": 1},
        )
        self.assertEqual(len(diagnostic_basis["direct_non_official_samples"]), 2)
        self.assertIn("upstream_state", diagnostic_basis["direct_non_official_samples"][0])
        display_values = {
            sample.get("upstream_state_display")
            for sample in diagnostic_basis["direct_non_official_samples"]
        }
        self.assertIn(
            "legacy_upstream_state_not_current_approval:reviewed",
            display_values,
        )
        self.assertIn(
            "legacy_upstream_state_not_current_approval:auto_linked",
            display_values,
        )
        self.assertNotIn("review_status", diagnostic_basis["direct_non_official_samples"][0])
        self.assertTrue(basis["review_only"])
        self.assertTrue(basis["non_scoring"])
        self.assertEqual(sources[0]["visible_count"], 0)
        self.assertEqual(
            sources[1]["direct_non_official_counts"],
            {"ncs_derived_learning_plan": 1, "report_training_course": 1},
        )
        self.assertIn("gap_reason=no_official_direct_learning_module_link", display)
        self.assertIn("direct_non_official_counts", display)
        self.assertIn("counts_as_official_learning_module=False", diagnostic_display)
        self.assertIn("direct_non_official_counts", source_display)
        self.assertIn("official=0", markdown)
        self.assertIn("Non-official diagnostics", markdown)
        self.assertIn("non_official_diagnostic", markdown)
        self.assertIn(
            "upstream_state_display=legacy_upstream_state_not_current_approval:reviewed",
            markdown,
        )
        self.assertIn(
            "upstream_state_display=legacy_upstream_state_not_current_approval:auto_linked",
            markdown,
        )
        self.assertNotIn("diagnostic_non_official", markdown)
