            csv_out = tmp_path / "decision_sheet.csv"
            html_out = tmp_path / "decision_sheet.html"
            write_aihr_plan_review_decision_sheet_csv(report, csv_out)
            write_aihr_plan_review_decision_sheet_html(report, html_out)
            audit_report = build_aihr_plan_review_decision_audit(
                decision_sheet_path=csv_out,
                request_order_path=request_order_path,
            )
            with csv_out.open(encoding="utf-8-sig", newline="") as handle:
                rows = list(csv.DictReader(handle))
            csv_text = csv_out.read_text(encoding="utf-8-sig")
            html = html_out.read_text(encoding="utf-8")
            summary = {key: value for key, value in report.items() if key != "rows"}
            summary["out_path"] = str(tmp_path / "decision_sheet.json")
