        self.assertFalse(report["db_writes"])
        self.assertFalse(report["status_update_allowed"])
        self.assertFalse(report["source_packet_prefill_allowed"])
        self.assertFalse(report["source_packet_prefill_ignored"])
        self.assertTrue(report["review_policy"]["source_packet_blank_until_human_decision"])
        self.assertEqual(
            report["review_policy"]["allowed_decisions"],
            ["include_in_draft", "exclude_from_draft", "defer"],
        )
        self.assertNotIn("legacy_decision_aliases", report["review_policy"])
        self.assertEqual(len(rows), report["row_count"])
        self.assertNotIn("rows", summary)
        self.assertEqual(rows[0]["target_label"], "'=cmd|' /C calc'!A0")
        self.assertEqual(rows[0]["review_question"], "' @confirm whether this course should remain in the matrix.")
        self.assertEqual(rows[0]["ncs_cl_cd"], "0202020101_23v3")
        self.assertEqual(rows[0]["major_code"], "02")
        self.assertEqual(rows[0]["decision"], "")
        self.assertEqual(rows[0]["source_packet"], "")
        self.assertEqual(rows[0]["status_update_allowed"], "false")
        self.assertTrue(audit_report["ok"])
        self.assertNotIn(
            "decision_sheet_request_order_row_mismatch",
            {finding["code"] for finding in audit_report["findings"]},
        )
        self.assertIn("=cmd|&#x27; /C calc&#x27;!A0", html)
        self.assertIn("status_update_allowed", html)
        self.assertEqual(html.count("<tr>") - 1, len(rows))
        self.assertNotIn("source_payload", summary_text)
        self.assertNotIn("legacy_decision_aliases", summary_text)
        self.assertNotIn("source_payload", csv_text)
        self.assertNotIn("source_payload", html)

