    def test_aihr_human_review_packet_label_contract_rewrites_course_roles(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            html_path = tmp_path / "aihr_human_review_packet.html"
            html_path.write_text(
                "\n".join(
                    [
                        "<!doctype html><html><body>",
                        '<div class="policy">learning modules are auxiliary_review_reference only.</div>',
                        (
                            "<span>roles current_query:1, expected_course:2, "
                            "recommended_course:3, target_query:1</span>"
                        ),
                        "<ul>",
                        "<li><b>expected_course</b> HR planning -> module.pdf</li>",
                        "<li><b>recommended_course</b> HR planning -> module.pdf</li>",
                        "<li><b>expected_course_context_module</b> already repaired</li>",
                        "</ul>",
                        "</body></html>",
                    ]
                ),
                encoding="utf-8",
            )
            report = repair_aihr_human_review_packet_labels(html_path=html_path)
            md_out = tmp_path / "label_contract.md"
            write_aihr_human_review_packet_label_contract_markdown(report, md_out)
            html = html_path.read_text(encoding="utf-8")
            markdown = md_out.read_text(encoding="utf-8")

        self.assertTrue(report["ok"])
        self.assertTrue(report["changed"])
        self.assertTrue(report["policy_note_added"])
        self.assertEqual(report["replacement_counts"]["expected_course"], 2)
        self.assertEqual(report["replacement_counts"]["recommended_course"], 2)
        self.assertEqual(report["bare_role_counts_after"]["expected_course"], 0)
        self.assertEqual(report["bare_role_counts_after"]["recommended_course"], 0)
        self.assertIn("current_query_context_module:1", html)
        self.assertIn("<b>expected_course_context_module</b>", html)
        self.assertIn("<b>recommended_course_context_module</b>", html)
        self.assertIn('data-contract="context_module_label_policy"', html)
        self.assertRegex(markdown, r"expected_course: 0")
        self.assertRegex(markdown, r"recommended_course_context_module: 2")
        self.assertNotRegex(html, r"(?<![A-Za-z0-9_])expected_course(?![A-Za-z0-9_])")
        self.assertNotRegex(html, r"(?<![A-Za-z0-9_])recommended_course(?![A-Za-z0-9_])")

