    def test_aihr_plan_review_workflow_handoff_prefers_triage_sidecars_over_derived_fallbacks(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            seedpack_path = tmp_path / "aihr_plan_review_seedpack_20260625_next.json"
            request_order_path = tmp_path / "request_order.json"
            decision_sheet_path = tmp_path / "decision_sheet.json"
            decision_audit_path = tmp_path / "decision_audit.json"
