    def test_aihr_plan_review_basis_coverage_reports_global_unique_sources_across_rows(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_path = Path(tmp)
            seedpack_path = tmp_path / "seedpack.json"
            request_order_path = tmp_path / "request_order.json"
            decision_audit_path = tmp_path / "decision_audit.json"
